package ssh

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"testing"

	gossh "golang.org/x/crypto/ssh"

	"github.com/zdva/tako/internal/model"
	"github.com/zdva/tako/internal/secrets"
	"github.com/zdva/tako/internal/transport"
)

// The fixtures in testdata/ppk were generated by puttygen 0.83 with the
// passphrase "secret"; they protect nothing.
const ppkPassphrase = "secret"

type fixedPrompter struct {
	pass  string
	calls int
}

func (p *fixedPrompter) ConfirmHostKey(context.Context, transport.HostKeyRequest) (bool, error) {
	return true, nil
}

func (p *fixedPrompter) Secret(context.Context, transport.SecretRequest) (transport.SecretReply, error) {
	p.calls++
	return transport.SecretReply{Value: []byte(p.pass)}, nil
}

func (p *fixedPrompter) Challenge(context.Context, transport.ChallengeRequest) ([]string, error) {
	return nil, transport.ErrCanceled
}

func TestParsePPK(t *testing.T) {
	t.Parallel()
	files, err := filepath.Glob(filepath.Join("testdata", "ppk", "*.ppk"))
	if err != nil || len(files) < 9 {
		t.Fatalf("fixtures: %v (%d files)", err, len(files))
	}
	for _, file := range files {
		t.Run(filepath.Base(file), func(t *testing.T) {
			t.Parallel()
			data, err := os.ReadFile(file)
			if err != nil {
				t.Fatal(err)
			}
			prompter := &fixedPrompter{pass: ppkPassphrase}
			a := &authSet{ctx: t.Context(), prompter: prompter, secrets: secrets.NewMemory()}
			signer, err := a.parsePPK(0, model.Auth{Kind: model.AuthKey, KeyPath: file}, data)
			if err != nil {
				t.Fatal(err)
			}
			f, _ := readPPK(data)
			wantPrompt := 0
			if f.encrypted() {
				wantPrompt = 1
			}
			if prompter.calls != wantPrompt {
				t.Errorf("passphrase asked %d times, want %d", prompter.calls, wantPrompt)
			}
			// The signer must match the file's public key and really sign.
			if got := signer.PublicKey().Marshal(); string(got) != string(f.pub) {
				t.Error("signer public key differs from the file's public blob")
			}
			msg := []byte("tako")
			sig, err := signer.Sign(nil, msg)
			if err != nil {
				t.Fatal(err)
			}
			if err := signer.PublicKey().Verify(msg, sig); err != nil {
				t.Errorf("signature does not verify: %v", err)
			}
		})
	}
}

func TestParsePPK_WrongPassphrase(t *testing.T) {
	t.Parallel()
	data, err := os.ReadFile(filepath.Join("testdata", "ppk", "ed25519-enc.ppk"))
	if err != nil {
		t.Fatal(err)
	}
	prompter := &fixedPrompter{pass: "nope"}
	a := &authSet{ctx: t.Context(), prompter: prompter}
	_, err = a.parsePPK(0, model.Auth{Kind: model.AuthKey, KeyPath: "x"}, data)
	if !errors.Is(err, transport.ErrAuthFailed) {
		t.Fatalf("err = %v, want ErrAuthFailed", err)
	}
	if prompter.calls != maxPassphraseTries {
		t.Errorf("asked %d times, want %d", prompter.calls, maxPassphraseTries)
	}
}

func TestReadPPK_Garbage(t *testing.T) {
	t.Parallel()
	for _, in := range []string{"", "PuTTY-User-Key-File-3: ssh-rsa\n", "PuTTY-User-Key-File-3: ssh-rsa\nEncryption: none\nPublic-Lines: 99999999\n"} {
		if _, err := readPPK([]byte(in)); !errors.Is(err, ErrBadPPK) {
			t.Errorf("readPPK(%q) err = %v, want ErrBadPPK", in, err)
		}
	}
	var _ gossh.Signer
}

func FuzzReadPPK(f *testing.F) {
	data, err := os.ReadFile(filepath.Join("testdata", "ppk", "rsa-enc.ppk"))
	if err == nil {
		f.Add(data)
	}
	f.Add([]byte("PuTTY-User-Key-File-2: ssh-rsa\nEncryption: none\n"))
	f.Fuzz(func(_ *testing.T, in []byte) {
		pf, err := readPPK(in)
		if err != nil {
			return
		}
		_, _ = pf.signer(nil)
	})
}
